window.OmniFeature=a=>{let observer=null,timer=null,scans=0,seen=new WeakSet();const rules=[['onetrust','#onetrust-reject-all-handler'],['cookiebot','#CybotCookiebotDialogBodyButtonDecline']];function scan(){timer=null;if(!a.active||document.hidden||scans++>=100){if(scans>=100)observer?.disconnect();return}const provider=a.settings.get('provider');for(const [name,selector]of rules){if(provider!=='both'&&provider!==name)continue;const button=document.querySelector(selector);if(!button||seen.has(button)||button.disabled||button.closest('[hidden],[inert]')||!button.getClientRects().length||getComputedStyle(button).visibility==='hidden')continue;const label=(button.textContent||'').trim().replace(/\s+/g,' ').toLowerCase();if(!/^(reject all|reject all cookies|decline|decline all|only necessary cookies|use necessary cookies only)$/.test(label))continue;seen.add(button);button.click();a.toast('Pressed the banner’s reject option.').catch(()=>{})}}function schedule(){if(document.hidden||!a.active)return;if(timer===null&&scans<100)timer=setTimeout(scan,250)}function stop(){document.removeEventListener('visibilitychange',schedule);observer?.disconnect();observer=null;clearTimeout(timer);timer=null}return{enable(){document.addEventListener('visibilitychange',schedule);scans=0;seen=new WeakSet();observer=new MutationObserver(schedule);observer.observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','disabled']});scan()},disable:stop}};